const html = document.documentElement.outerHTML;
const findAll = (re) => [...new Set((html.match(re)||[]))];
const result = {
  title: document.title,
  canonical: document.querySelector('link[rel=canonical]')?.href || null,
  ogUrl: document.querySelector('meta[property="og:url"]')?.content || null,
  test_refs: findAll(/test\.td-group\.jp[^\s"'<>]*/gi),
  http_insecure: findAll(/http:\/\/(?!localhost)[^\s"'<>]*td-group[^\s"'<>]*/gi),
  staging_words: findAll(/(staging|dev\.|\/test\/|test-|localhost|127\.0\.0\.1)[^\s"'<>]{0,30}/gi).slice(0,20),
  htmlLength: html.length,
};
result;

async function grab(u){ try{ const r = await fetch(u); const t = await r.text(); return {u, status:r.status, testHits:[...new Set((t.match(/test\.td-group\.jp[^\s"'<>]*/gi)||[]))], httpHits:[...new Set((t.match(/http:\/\/[^\s"'<>]*td-group[^\s"'<>]*/gi)||[]))], len:t.length}; }catch(e){ return {u, err:String(e)}; } }
const urls = ['/sitemap.xml','/wp-sitemap.xml','/sitemap_index.xml','/robots.txt','/feed/','/company/','/?page_id=2'];
const out = [];
for(const u of urls){ out.push(await grab(u)); }
out;

const sm = await (await fetch('/sitemap.xml')).text();
const rb = await (await fetch('/robots.txt')).text();
({sitemap: sm, robots: rb});

const subs = ['post','page','news','clinic','symptoms','category','author'];
let allLocs = [];
let report = [];
for (const s of subs){
  try{
    const t = await (await fetch(`/${s}-sitemap.xml`)).text();
    const locs = [...t.matchAll(/<loc><!\[CDATA\[(.*?)\]\]><\/loc>/g)].map(m=>m[1]);
    allLocs.push(...locs);
    const bad = locs.filter(u=>/test\.td-group|http:\/\//i.test(u));
    report.push({sitemap:s, count:locs.length, bad});
  }catch(e){ report.push({sitemap:s, err:String(e)}); }
}
// Now scan a sample of real pages for test-env references in HTML
const sample = allLocs.slice(0, 12);
let pageHits = [];
for (const u of sample){
  try{
    const h = await (await fetch(u)).text();
    const test = [...new Set((h.match(/test\.td-group\.jp[^\s"'<>]*/gi)||[]))];
    const http = [...new Set((h.match(/http:\/\/(?!www\.w3\.org|schema\.org|gmpg\.org|purl\.org|ogp\.me)[^\s"'<>]*/gi)||[]))].filter(x=>/td-group/i.test(x));
    if(test.length||http.length) pageHits.push({u, test, http});
  }catch(e){}
}
({report, totalUrls: allLocs.length, sampleScanned: sample.length, pageHits});

