const subs = ['post','page','news','clinic','symptoms'];
let allLocs = [];
for (const s of subs){
  const t = await (await fetch(`/${s}-sitemap.xml`)).text();
  allLocs.push(...[...t.matchAll(/<loc><!\[CDATA\[(.*?)\]\]><\/loc>/g)].map(m=>m[1]));
}
let pageHits = [];
for (const u of allLocs){
  try{
    const h = await (await fetch(u)).text();
    const test = [...new Set((h.match(/test\.td-group\.jp[^\s"'<>]*/gi)||[]))];
    const httpImg = [...new Set((h.match(/http:\/\/[a-z0-9.\-]*td-group\.jp[^\s"'<>]*/gi)||[]))];
    if(test.length||httpImg.length) pageHits.push({u, test, httpImg});
  }catch(e){ pageHits.push({u, err:String(e)}); }
}
({scanned: allLocs.length, pageHits});

const subs = ['post','page','news','clinic','symptoms'];
let allLocs = [];
for (const s of subs){
  const t = await (await fetch(`/${s}-sitemap.xml`)).text();
  allLocs.push(...[...t.matchAll(/<loc><!\[CDATA\[(.*?)\]\]><\/loc>/g)].map(m=>m[1]));
}
window.__locs = allLocs;
async function scan(list){
  let hits=[];
  for(const u of list){
    try{
      const h = await (await fetch(u)).text();
      const test=[...new Set((h.match(/test\.td-group\.jp[^\s"'<>]*/gi)||[]))];
      const http=[...new Set((h.match(/http:\/\/[a-z0-9.\-]*td-group\.jp[^\s"'<>]*/gi)||[]))];
      if(test.length||http.length) hits.push({u,test,http});
    }catch(e){ hits.push({u,err:String(e)}); }
  }
  return hits;
}
window.__scan = scan;
({total: allLocs.length, batch1: await scan(allLocs.slice(0,15))});

